def test_haproxy_capture_serializes_selected_metrics():
    capture = HaproxyCapture(r"web", r"BACKEND", ["scur", "rate", "qcur"])
    row = {"pxname": "web", "svname": "BACKEND", "scur": "3", "rate": "1.5", "qcur": ""}
