    assert list(capture.to_graphite_events("stats.ol.haproxy", row, 123.9)) == [
        GraphiteEvent("stats.ol.haproxy.web.BACKEND.scur", 3.0, 123),
        GraphiteEvent("stats.ol.haproxy.web.BACKEND.rate", 1.5, 123),
